# Public API (cm:*)
  @api cm:setContext(newTake)  @ 415-420
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 413
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 414
  @api cm:clearTake()  @ 422-427
  @api cm:boundTake()  @ 430
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 429
  @api cm:boundTrack()  @ 433
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 432
  @api cm:setTrack(newTrack)  @ 435-440
  @api cm:pollUndo()  @ 443
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 442
  @api cm:isDeclared(key)  @ 480
      @contract  non-raising existence test against the schema; true iff key is declared  @ 479
  @api cm:get(key, opts)  @ 484-488
      @contract  deep-copy of resolved value (most-specific tier, else default); raises on unknown key  @ 482
      @contract  opts.mergeTiers=true → per-subkey union across defaults+tiers; table-valued keys only  @ 483
  @api cm:getAt(level, key)  @ 491-500
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 490
  @api cm:valueFor(handle, scope, key)  @ 503-510
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 502
  @api cm:defaultFor(key)  @ 513-516
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 512
  -- Writing
  @api cm:set(level, key, value)  @ 521-531
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 520
  @api cm:remove(level, key)  @ 534-545
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 533
  @api cm:assign(level, updates)  @ 548-562
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 547

